// Parity checks of the Irodori text layer (src/irodori/text/) against the Python source of truth.
//
// The fixture `irodori-text/parity.json` is generated by the exporter
// (tools/exporter/irodori_tokenizer.py). It holds
//  - 33 `{raw, normalized}` cases of `normalize_text` (each replacement rule fired at least once)
//  - 14 `{raw, normalized, ids}` tokenizer cases and 3 cases of `batch_encode`'s final form. **The
//    source of truth is two paths, tokenizers and transformers**, and their agreement was measured
//    at emit time
//  - 6 cases with the id sequences of the caption path (upstream only strips) and the text path
//    (normalize), both taken from the same raw text
//  - the **subset** of the vocabulary needed to reproduce them (the 102,400 entries are not
//    committed; the exporter measures that the lattice equals the full vocabulary's by scanning the
//    whole vocabulary in reverse)
//  - **the whole** table of single code points whose NFKC is not the identity
//  - the rare-token split (ADR 0149): upstream's table cut to the subset and 8 cases, each solved by
//    upstream with the split off and on (4 of them also in `batch_encode`'s final form)
//
// It depends on neither real assets (under outputs/) nor a GPU, so it always runs.
//
// What is pinned is behaviour: "the same raw text gives the same id sequence as Python". How the
// tables are held or how the text is split internally is not pinned.

import { readTextFile } from "@karume/test-support/fs";
import { test } from "vite-plus/test";
import { assert, assertEquals, assertNotEquals, assertThrows } from "@std/assert";
import { ModelInputError } from "../src/errors.ts";
import { packCaptionIds, packIds } from "../src/irodori/host/pack.ts";
import { normalizeText } from "../src/irodori/text/normalize.ts";
import {
  IrodoriTokenizer,
  type IrodoriTokenizerAssets,
  parseIrodoriTokenizerAsset,
} from "../src/irodori/text/tokenizer.ts";

type EncodeCase = {
  readonly name: string;
  readonly why: string;
  readonly raw: string;
  readonly normalized: string;
  readonly ids: number[];
};

type BatchCase = {
  readonly name: string;
  readonly why: string;
  readonly raw: string;
  readonly normalized: string;
  readonly maxLength: number;
  readonly idsPadded: number[];
  readonly mask: boolean[];
};

type CaptionCase = {
  readonly name: string;
  readonly why: string;
  readonly raw: string;
  readonly stripped: string;
  readonly normalized: string;
  readonly maxLength: number;
  readonly idsPacked: number[];
  readonly normalizedIdsPacked: number[];
  readonly normalizeSensitive: boolean;
};

type SplitCase = {
  readonly name: string;
  readonly why: string;
  readonly raw: string;
  readonly normalized: string;
  readonly ids: number[];
  readonly idsSplit: number[];
  readonly maxLength?: number;
  readonly idsPadded?: number[];
  readonly mask?: boolean[];
  readonly idsPaddedSplit?: number[];
  readonly maskSplit?: boolean[];
};

type NormalizeCase = {
  readonly name: string;
  readonly why: string;
  readonly raw: string;
  readonly normalized: string;
};

type Fixture = {
  readonly asset: {
    readonly vocab: [string, number, number][];
    readonly minScore: number;
    readonly maxTokenLength: number;
    readonly addedTokens: [string, number][];
    readonly bosId: number;
    readonly padId: number;
    readonly unkId: number;
    readonly byteBaseId: number;
    readonly rareTokenSplit: {
      readonly disabledScore: number;
      readonly disabledIds: number[];
      readonly forcedSplits: [number, number[]][];
      readonly minScore: number;
      readonly disabledTotal: number;
    };
  };
  readonly encode: {
    readonly cases: EncodeCase[];
    readonly batch: BatchCase[];
    readonly caption: CaptionCase[];
    readonly split: SplitCase[];
  };
  readonly normalize: { readonly cases: NormalizeCase[] };
  readonly nfkcDiff: Record<string, string>;
};

const FIXTURE_PATH = new URL("./fixtures/irodori-text/parity.json", import.meta.url);
const fixture = JSON.parse(await readTextFile(FIXTURE_PATH)) as Fixture;

const assets: IrodoriTokenizerAssets = {
  vocab: new Map(fixture.asset.vocab.map(([token, id, score]) => [token, { id, score }])),
  // MUST: not derived from the subset — the unknown-node score and the search width come from the
  // **whole** vocabulary.
  minScore: fixture.asset.minScore,
  maxTokenLength: fixture.asset.maxTokenLength,
  unkId: fixture.asset.unkId,
  byteBaseId: fixture.asset.byteBaseId,
  bosId: fixture.asset.bosId,
  padId: fixture.asset.padId,
  addedTokens: new Map(fixture.asset.addedTokens),
};

const tokenizer = new IrodoriTokenizer(assets);

/** The unsplit path (every case of the fixture before `encode.split` is upstream's plain encoding). */
const PLAIN = { splitRareTokens: false } as const;
/** The rare-token split path (ADR 0149). */
const SPLIT = { splitRareTokens: true } as const;

/**
 * The same subset with the split table. MUST: `minScore` of the split side comes from the
 * **whole replaced-score** vocabulary (the recipe's `split_min_score`), not from the subset or the
 * original minimum.
 */
const splitTokenizer = new IrodoriTokenizer({
  ...assets,
  rareTokenSplit: {
    disabledScore: fixture.asset.rareTokenSplit.disabledScore,
    disabledIds: fixture.asset.rareTokenSplit.disabledIds,
    minScore: fixture.asset.rareTokenSplit.minScore,
    forcedSplits: new Map(fixture.asset.rareTokenSplit.forcedSplits),
  },
});

// ---- The fixture itself -------------------------------------------------------

test("the fixture is not empty (a mix-up has not turned every case into a pass)", () => {
  // Placed first. If a misread / failed generation left the cases empty, the loops below would run
  // zero times and "green but verifying nothing" would silently hold.
  assertEquals(fixture.encode.cases.length, 14);
  assertEquals(fixture.encode.batch.length, 3);
  assertEquals(fixture.normalize.cases.length, 33);
  assert(
    fixture.asset.vocab.length > 256,
    `the vocabulary subset has ${fixture.asset.vocab.length} entries`,
  );
  assert(Object.keys(fixture.nfkcDiff).length > 4000, "the NFKC difference table is too thin");
  // MUST: the unknown-node weight comes from the minimum score of the **whole** vocabulary. If it
  // equals the subset's minimum, either the fixture or the assembly did not take it from the whole.
  // The golden id sequences cannot detect this difference (no known token competes in the unknown
  // span, so the path does not change — measured by fault injection), so the value itself is pinned
  // here.
  const subsetMin = Math.min(...fixture.asset.vocab.map(([, , score]) => score));
  assert(
    assets.minScore < subsetMin,
    `minScore ${assets.minScore} equals the subset's minimum ${subsetMin}`,
  );
});

// ---- ① Normalisation (isolated before the tokenizer) ------------------------

for (const testCase of fixture.normalize.cases) {
  test(`normalisation parity [${testCase.name}] ${testCase.why}`, () => {
    assertEquals(normalizeText(testCase.raw), testCase.normalized);
  });
}

// ---- ② Encoding (raw text → id sequence) ------------------------------------

for (const testCase of fixture.encode.cases) {
  test(`encoding parity [${testCase.name}] ${testCase.why}`, () => {
    // Also compare the intermediate (the normalised string) — looking at the full path alone would
    // miss a normalisation mistake and an encoding mistake that cancel out.
    assertEquals(normalizeText(testCase.raw), testCase.normalized, "the normalised string");
    assertEquals(
      tokenizer.encode(testCase.normalized, PLAIN),
      testCase.ids,
      "the id sequence from the normalised text",
    );
    assertEquals(
      tokenizer.encode(normalizeText(testCase.raw), PLAIN),
      testCase.ids,
      "the full path from the raw text",
    );
  });
}

test("encoding: byte_fallback is exactly the UTF-8 bytes (reproducible without looking at the vocabulary)", () => {
  // The expected value of the c case (an out-of-vocabulary emoji) is built from UTF-8,
  // independently of the fixture's id sequence. A `byteBaseId` mix-up fails here.
  const byteCase = fixture.encode.cases.find((entry) => entry.name === "emoji-byte-fallback");
  assert(byteCase !== undefined, "the fixture has no c case");
  const bytes = new TextEncoder().encode(byteCase.raw);
  assertEquals(
    byteCase.ids,
    [...bytes].map((byte) => fixture.asset.byteBaseId + byte),
  );
});

test("assets: the ids of the 256 byte tokens run consecutively as byteBaseId + byte value", () => {
  // The very premise of byte_fallback's id arithmetic (the expansion in `unigram.ts`).
  for (let byte = 0; byte < 256; byte++) {
    const token = `<0x${byte.toString(16).toUpperCase().padStart(2, "0")}>`;
    const entry = assets.vocab.get(token);
    assert(entry !== undefined, `${token} is not in the vocabulary subset`);
    assertEquals(entry.id, fixture.asset.byteBaseId + byte, `id of ${token}`);
  }
});

// ---- ③ The final form of batch_encode (BOS prefix + truncation + right pad + mask) ----

for (const testCase of fixture.encode.batch) {
  test(`assembly parity [${testCase.name}] ${testCase.why}`, () => {
    const padded = tokenizer.encodePadded(testCase.normalized, testCase.maxLength, PLAIN);
    assertEquals([...padded.ids], testCase.idsPadded, "idsPadded");
    assertEquals([...padded.mask], testCase.mask.map(Number), "mask");
  });
}

test("assembly: truncation really fires, BOS remains, and the total length is max_length", () => {
  const truncated = fixture.encode.batch.find((entry) => entry.name === "batch-truncated");
  assert(truncated !== undefined, "the fixture has no truncation case");
  // A fault that mistakes the body's budget for `max_length` fails this case's id-sequence parity
  // (with only cases where truncation does not fire, it would pass).
  assert(
    tokenizer.encode(truncated.normalized, PLAIN).length + 1 > truncated.maxLength,
    "truncation did not fire",
  );
  assertEquals(truncated.idsPadded.length, truncated.maxLength);
  assertEquals(truncated.idsPadded[0], fixture.asset.bosId);
  assertEquals(truncated.mask.filter(Boolean).length, truncated.maxLength);
});

test("assembly: a short input is right-padded and the mask marks the valid length", () => {
  const short = fixture.encode.batch.find((entry) => entry.name === "batch-short");
  assert(short !== undefined, "the fixture has no short case");
  const used = tokenizer.encode(short.normalized, PLAIN).length + 1;
  assertEquals(short.mask.filter(Boolean).length, used);
  assertEquals(
    short.idsPadded.slice(used),
    Array(short.maxLength - used).fill(fixture.asset.padId),
  );
});

// ---- ③' The caption path (upstream only strips; normalize is for text only) ----
//
// Upstream `inference_runtime._synthesize` applies only `str(...).strip()` to the caption, and
// `normalize_text` is for text only. If this is not aligned, the conditioning silently becomes
// something else with no exception or warning (by the outer-bracket stripping, NFKC and symbol
// removal), so the fixture holds **the id sequences of the same raw text through both paths** and
// both are compared.

for (const testCase of fixture.encode.caption) {
  test(`caption parity [${testCase.name}] ${testCase.why}`, () => {
    assertEquals(
      [...packCaptionIds(tokenizer, testCase.raw, testCase.maxLength)],
      testCase.idsPacked,
      "caption path (strip only)",
    );
    assertEquals(
      [...packIds(tokenizer, testCase.raw, testCase.maxLength, "text", PLAIN)],
      testCase.normalizedIdsPacked,
      "text path (normalize + strip)",
    );
    assertEquals(normalizeText(testCase.raw).trim(), testCase.normalized, "the normalised string");
  });
}

test("caption: the id sequences of the two paths really differ (evidence the check is not vacuous)", () => {
  // With no cases, the loop would run zero times and "green but verifying nothing" would silently
  // hold.
  assertEquals(fixture.encode.caption.length, 6);
  const sensitive = fixture.encode.caption.filter((entry) => entry.normalizeSensitive);
  assert(sensitive.length >= 5, `only ${sensitive.length} cases are sensitive to normalisation`);
  for (const entry of sensitive) {
    assertNotEquals(
      entry.idsPacked,
      entry.normalizedIdsPacked,
      `${entry.name} is the same on both paths`,
    );
  }
  // The official Voice Design sentence is insensitive to normalisation = the existing goldens (the
  // caption ones) are on the side this fix does not move.
  const insensitive = fixture.encode.caption.filter((entry) => !entry.normalizeSensitive);
  assertEquals(
    insensitive.map((entry) => entry.name),
    ["caption-official"],
  );
  for (const entry of insensitive) {
    assertEquals(entry.idsPacked, entry.normalizedIdsPacked);
  }
});

// ---- ④ NFKC (source of truth = Python's unicodedata / this side = the JS engine's ICU) ----

test("NFKC: matches the source of truth's difference table exactly for every code point except surrogates", () => {
  // Both directions are checked: a case in the table that JS does not change (= the source of truth
  // is newer) and a case not in the table that JS changes (= JS is newer) both quietly split the
  // normalisation result. An assert per entry would be 1.1M calls, so the comparison happens in the
  // loop and only the mismatches are collected.
  const mismatches: string[] = [];
  for (let cp = 0; cp < 0x110000; cp++) {
    if (cp >= 0xd800 && cp <= 0xdfff) continue;
    const source = String.fromCodePoint(cp);
    const want = fixture.nfkcDiff[String(cp)] ?? source;
    const got = source.normalize("NFKC");
    if (got !== want && mismatches.length < 8) {
      mismatches.push(`U+${cp.toString(16).toUpperCase()}: table=${want} JS=${got}`);
    }
  }
  // Known difference of Unicode versions, not of the runtime: the reference table was generated by
  // Python's unicodedata of an earlier Unicode version, while Node 24's ICU 78 implements Unicode
  // 17.0, which added the compatibility mapping U+A7F1 → "S". Deno 2.9 (older ICU) matched the
  // table exactly. Any other difference still fails; the list is updated only with the Unicode
  // release that explains the new entry (or by regenerating the table with a matching unicodedata).
  const KNOWN_UNICODE_VERSION_DIFFERENCES = ["U+A7F1: table=\u{A7F1} JS=S"];
  assertEquals(
    mismatches,
    mismatches.length === 0 ? [] : KNOWN_UNICODE_VERSION_DIFFERENCES,
    "some code points' NFKC differs from the source of truth",
  );
});

// ---- ⑤ The asset parser (an external boundary) ------------------------------

/** Byte value → byte_fallback spelling (`<0x00>`..`<0xFF>`). */
const byteToken = (byte: number): string =>
  `<0x${byte.toString(16).toUpperCase().padStart(2, "0")}>`;

/** The spellings of the 256 bytes (the rows laid out consecutively from `byteBaseId`). */
const BYTE_TOKENS: readonly string[] = Array.from({ length: 256 }, (_, byte) => byteToken(byte));

/**
 * `byteBaseId` is the start of 256 consecutive rows, so checking the success path needs a
 * vocabulary that satisfies `id + 255 < vocabulary row count` (G4-02). This appends the 256 byte
 * rows right after the real tokens and returns their start as `byteBaseId` (as in the distribution,
 * the consecutive rows are spelled `<0xNN>`). The byte rows all get score 0 (above the real minimum
 * score), so `minScore` is not thrown off.
 */
const padVocabForByteBase = (
  realTokens: readonly string[],
  realScores: readonly number[],
): { vocabText: string; scores: number[]; byteBaseId: number } => ({
  vocabText: [...realTokens, ...BYTE_TOKENS].join("\n"),
  scores: [...realScores, ...Array(BYTE_TOKENS.length).fill(0)],
  byteBaseId: realTokens.length,
});

test("asset parser: builds the asset tables from plain JSON, mapping id / score by row number", () => {
  const { vocabText, scores, byteBaseId } = padVocabForByteBase(
    ["<unk>", "<s>", "<pad>", "▁こんにちは", "世界"],
    [0, 0, 0, -1.5, -2.5],
  );
  const parsed = parseIrodoriTokenizerAsset({
    vocabText,
    scores,
    addedTokens: [
      ["<unk>", 0],
      ["<s>", 1],
      ["<pad>", 2],
    ],
    bosId: 1,
    padId: 2,
    unkId: 0,
    byteBaseId,
  });
  assertEquals(parsed.vocab.get("世界"), { id: 4, score: -2.5 });
  assertEquals(parsed.minScore, -2.5);
  // The search width counts code points (`▁こんにちは` = 6 — neither UTF-16 units nor bytes).
  assertEquals(parsed.maxTokenLength, 6);
  assertEquals(parsed.bosId, 1);
  assertEquals([...parsed.addedTokens.keys()], ["<unk>", "<s>", "<pad>"]);
});

test("asset parser: a row-count mismatch and a missing required key fail loudly", () => {
  const { vocabText, scores, byteBaseId } = padVocabForByteBase(
    ["<unk>", "<s>", "<pad>"],
    [0, 0, 0],
  );
  const base = {
    vocabText,
    scores,
    addedTokens: [["<unk>", 0]],
    bosId: 1,
    padId: 2,
    unkId: 0,
    // The real tokens are 3 rows (the 256 byte rows come after them — see the doc above).
    byteBaseId,
  };
  // Viterbi does not fail with one score missing (fragments not in the vocabulary escape to the
  // byte expansion), so without failing here every id would silently shift.
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, scores: [0, 0] }),
    Error,
    "the length of scores",
  );
  for (const key of [
    "vocabText",
    "scores",
    "addedTokens",
    "bosId",
    "padId",
    "unkId",
    "byteBaseId",
  ]) {
    const broken: Record<string, unknown> = { ...base };
    delete broken[key];
    assertThrows(
      () => parseIrodoriTokenizerAsset(broken),
      Error,
      key === "scores" ? "scores" : key,
    );
  }
  assertThrows(() => parseIrodoriTokenizerAsset(undefined), Error, "not an object");
});

test("asset parser: special ids are integers below the vocabulary row count (rejected before Int32Array silently truncates them)", () => {
  const { vocabText, scores, byteBaseId } = padVocabForByteBase(
    ["<unk>", "<s>", "<pad>"],
    [0, 0, 0],
  );
  const VOCAB_SIZE = vocabText.split("\n").length;
  const base = {
    vocabText,
    scores,
    addedTokens: [["<unk>", 0]],
    bosId: 1,
    padId: 2,
    unkId: 0,
    byteBaseId,
  };
  // A non-integer is truncated on assignment to `Int32Array`, and an out-of-range value wraps —
  // both are silent wrong values that "point at a different token" and do not surface before the
  // graph's embedding gather.
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, unkId: 1.5 }),
    Error,
    "tokenizer.unkId: token id is not an integer in 0..2147483647 (1.5)",
  );
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, byteBaseId: -1 }),
    Error,
    "tokenizer.byteBaseId: token id is not an integer in 0..2147483647 (-1)",
  );
  // Exactly the vocabulary row count = one past the end (VOCAB_SIZE rows including the byte rows).
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, bosId: VOCAB_SIZE }),
    Error,
    `tokenizer.bosId: token id ${VOCAB_SIZE} is not below the vocabulary row count ${VOCAB_SIZE}`,
  );
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, addedTokens: [["<unk>", 0.5]] }),
    Error,
    "token id is not an integer in 0..2147483647 (0.5)",
  );
});

test("asset parser: an added token's id is below the vocabulary row count and matches the vocabulary row of the same spelling", () => {
  // encode puts added-token ids into the graph input as they are. An out-of-range id does not
  // surface before the embedding gather goes OOB, and a different id for the same spelling stays a
  // silent wrong value that "points at a different row".
  const VOCAB_SIZE = 300;
  const base = {
    vocabText: ["<s>", "<pad>", ...Array.from({ length: VOCAB_SIZE - 258 }, (_, i) => `t${i}`)]
      .concat(BYTE_TOKENS)
      .join("\n"),
    scores: Array.from({ length: VOCAB_SIZE }, () => 0),
    bosId: 0,
    padId: 1,
    unkId: 0,
    byteBaseId: VOCAB_SIZE - 256,
  };
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, addedTokens: [["<s>", 2147483647]] }),
    Error,
    'tokenizer.addedTokens: "<s>" has id 2147483647, which is >= the vocabulary row count 300',
  );
  // Boundary: exactly the row count is one past the end.
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, addedTokens: [["<x>", VOCAB_SIZE]] }),
    Error,
    `, which is >= the vocabulary row count ${VOCAB_SIZE}`,
  );
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, addedTokens: [["<s>", 1]] }),
    Error,
    'tokenizer.addedTokens: "<s>" has id 1, which disagrees with vocabulary row 0',
  );
  // Positive case: both a spelling matching the vocabulary and an in-range id for a spelling not in
  // the vocabulary pass.
  const parsed = parseIrodoriTokenizerAsset({
    ...base,
    addedTokens: [
      ["<s>", 0],
      ["<pad>", 1],
      ["<x>", VOCAB_SIZE - 1],
    ],
  });
  assertEquals(
    [...parsed.addedTokens],
    [
      ["<s>", 0],
      ["<pad>", 1],
      ["<x>", VOCAB_SIZE - 1],
    ],
  );
});

test("asset parser: byteBaseId requires the whole run of 256 byte rows to be inside the vocabulary (G4-02)", () => {
  const VOCAB_SIZE = 300;
  const base = {
    vocabText: [
      ...Array.from({ length: VOCAB_SIZE - 256 }, (_, i) => `t${i}`),
      ...BYTE_TOKENS,
    ].join("\n"),
    scores: Array.from({ length: VOCAB_SIZE }, () => 0),
    addedTokens: [],
    bosId: 0,
    padId: 0,
    unkId: 0,
  };
  // Negative case: with byteBaseId=299, 299..554 does not fit in the 300-row vocabulary.
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, byteBaseId: 299 }),
    Error,
    "the 256 bytes",
  );
  // Positive case: byteBaseId = 300 − 256 = 44 fits exactly (the 256 rows 44..299 run to the end).
  const parsed = parseIrodoriTokenizerAsset({ ...base, byteBaseId: 44 });
  assertEquals(parsed.byteBaseId, 44);
});

test("asset parser: the 256 rows from byteBaseId are spelled <0x00>..<0xFF> in order", () => {
  // Unknown characters expand to `byteBaseId + byte value`, so an asset with swapped rows gives ids
  // different from HF (which looks ids up by name) ("A" = 0x41 becomes the id of the `<0x42>` row).
  const VOCAB_SIZE = 300;
  const base = {
    scores: Array.from({ length: VOCAB_SIZE }, () => 0),
    addedTokens: [],
    bosId: 0,
    padId: 0,
    unkId: 0,
    byteBaseId: 44,
  };
  const words = Array.from({ length: VOCAB_SIZE - 256 }, (_, i) => `t${i}`);
  const swapped = [...BYTE_TOKENS];
  [swapped[0x41], swapped[0x42]] = [swapped[0x42], swapped[0x41]];
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, vocabText: [...words, ...swapped].join("\n") }),
    Error,
    `tokenizer.byteBaseId: row ${44 + 0x41} is not <0x41>`,
  );
  // A position off by one (starting at a vocabulary word) fails the same way.
  assertThrows(
    () =>
      parseIrodoriTokenizerAsset({
        ...base,
        vocabText: [...words, ...BYTE_TOKENS].join("\n"),
        byteBaseId: 43,
      }),
    Error,
    "tokenizer.byteBaseId: row 43 is not <0x00>",
  );
});

test("asset parser: rejects duplicate vocabulary lines and duplicate added-token keys (no `Map` last-one-wins)", () => {
  const VOCAB_SIZE = 300;
  const base = {
    vocabText: [
      ...Array.from({ length: VOCAB_SIZE - 256 }, (_, i) => `t${i}`),
      ...BYTE_TOKENS,
    ].join("\n"),
    scores: Array.from({ length: VOCAB_SIZE }, () => 0),
    addedTokens: [["t0", 0]],
    bosId: 0,
    padId: 0,
    unkId: 0,
    byteBaseId: 44,
  };
  // Positive case (the counterpart showing the check is not always true).
  assertEquals(parseIrodoriTokenizerAsset(base).vocab.size, VOCAB_SIZE);

  // Line number = id, so a duplicate line makes the earlier id unreachable. The row-count
  // comparison (the number of scores) does not change with duplicates, so it catches none of them.
  const duplicated = [
    ...Array.from({ length: VOCAB_SIZE - 256 }, (_, i) => `t${i}`),
    ...BYTE_TOKENS.slice(0, -1),
    "t0",
  ];
  assertThrows(
    () => parseIrodoriTokenizerAsset({ ...base, vocabText: duplicated.join("\n") }),
    Error,
    `tokenizer.vocabText: line ${VOCAB_SIZE - 1} has the same token as line 0`,
  );
  // Added tokens are split out **before** normalisation, so last-one-wins would quietly change the
  // id they are split out to.
  assertThrows(
    () =>
      parseIrodoriTokenizerAsset({
        ...base,
        addedTokens: [
          ["t0", 0],
          ["t0", 1],
        ],
      }),
    Error,
    "tokenizer.addedTokens: duplicate key ",
  );
});

test("asset parser: scores are finite (a polluted minScore collapses the unknown-node weight)", () => {
  const VOCAB_SIZE = 300;
  const scores = Array.from({ length: VOCAB_SIZE }, () => 0);
  const base = {
    vocabText: [
      ...Array.from({ length: VOCAB_SIZE - 256 }, (_, i) => `t${i}`),
      ...BYTE_TOKENS,
    ].join("\n"),
    scores,
    addedTokens: [],
    bosId: 0,
    padId: 0,
    unkId: 0,
    byteBaseId: 44,
  };
  // NaN pollutes minScore through `Math.min`, and ±Infinity collapses every path to the same value.
  // Neither raises an exception; they only give "a different split" (the count comparison does not
  // catch them).
  for (const bad of [Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
    assertThrows(
      () =>
        parseIrodoriTokenizerAsset({
          ...base,
          scores: scores.map((value, index) => (index === 7 ? bad : value)),
        }),
      Error,
      "tokenizer.scores[7]: not a finite number",
    );
  }
});

// ---- Boundaries (what the golden cases actually exercise) ------------------

test("does not accept an unpaired surrogate (no silent pass for input the source of truth does not have)", () => {
  // It arrives as the body of a generation request, so it is an input error (ADR 0107 decision 2 —
  // fixing the character makes it pass). The source of truth for the acceptance condition is still
  // the single `toCodePoints`, so the owner's diagnostic stays in `cause`.
  const error = assertThrows(
    () => tokenizer.encode("a\ud800b", PLAIN),
    ModelInputError,
    "surrogate",
  );
  assert(error.cause instanceof Error);
  assert(!(error.cause instanceof ModelInputError), "cause is the shared helper's plain Error");
  // The other side: paired surrogates (such as U+1F600) pass.
  assert(tokenizer.encode("a\ud83d\ude00b", PLAIN).length > 0);
});

test("added tokens are split out **before** the lattice (they do not lose to the vocabulary's split)", () => {
  // The 18 in the real assets are also in the vocabulary with the same spelling and id, so the g
  // case's id sequence cannot catch this rule (removing the split-out gives the same sequence —
  // measured by fault injection). A synthetic asset builds a shape where "running it through the
  // lattice gives a different sequence", and the rule is exercised directly.
  const vocab = new Map([
    ["<|x|>", { id: 5, score: -20 }],
    ["<|", { id: 6, score: -1 }],
    ["x", { id: 7, score: -1 }],
    ["|>", { id: 8, score: -1 }],
  ]);
  const base = {
    vocab,
    minScore: -20,
    maxTokenLength: 5,
    unkId: 0,
    byteBaseId: 100,
    bosId: 1,
    padId: 2,
  };
  const added = new IrodoriTokenizer({ ...base, addedTokens: new Map([["<|x|>", 99]]) });
  assertEquals(added.encode("<|x|>", PLAIN), [99], "the added token's id comes out directly");
  // Removed from the added tokens, the lattice wins with a three-way split (= evidence the check
  // above is not vacuous).
  const plain = new IrodoriTokenizer({ ...base, addedTokens: new Map() });
  assertEquals(
    plain.encode("<|x|>", PLAIN),
    [6, 7, 8],
    "the lattice chooses the three-way split by score sum",
  );
});

test("Metaspace: does not prepend ▁ (prepend_scheme=never)", () => {
  // The i case (starting with an ASCII space) gets ▁ from the replacement. An implementation that
  // prepends would give ▁▁ and a different id sequence.
  const leading = fixture.encode.cases.find((entry) => entry.name === "leading-space");
  const withSpaces = fixture.encode.cases.find((entry) => entry.name === "with-spaces");
  assert(leading !== undefined && withSpaces !== undefined, "the fixture has no i / h case");
  assert(leading.normalized.startsWith(" "), "the i case does not start with a space");
  // The first id of the h case, which has no leading space, is not the id of a token with ▁.
  const first = withSpaces.ids[0];
  const head = [...assets.vocab.entries()].find(([, entry]) => entry.id === first);
  assert(head !== undefined && !head[0].startsWith("▁"), `the first token ${head?.[0]} got ▁`);
});

// ---- Semantics and complexity of the outer-bracket stripping (③) -------------

test("outer-bracket stripping: semantics of mixed brackets and brackets closing midway", () => {
  // Shapes not in the parity fixture (brackets-*) are pinned with the same rule as the Python
  // source of truth `strip_outer_brackets` (strip only a pair of the same kind enclosing the whole
  // text, and after a strip, retry from the start). NFKC applies after the stripping, so remaining
  // full-width brackets become ASCII.
  const cases: readonly (readonly [string, string])[] = [
    ["「「あ」」", "あ"],
    ["（「（あ）」）", "あ"],
    ["「「あ」と「い」」", "「あ」と「い」"],
    ["「あ」「い」", "「あ」「い」"],
    ["「（あ」）", "「(あ」)"],
    ["((a)", "((a)"],
    ["(a))", "(a))"],
    ["(「a)」", "(「a)」"],
    ["「」", ""],
    ["「「」」", ""],
    ["「", "「"],
    ["「😀」", "😀"],
    ["『（あ）い』", "(あ)い"],
  ];
  for (const [raw, normalized] of cases) assertEquals(normalizeText(raw), normalized, raw);
});

test("outer-bracket stripping: strips in time linear in the input length even for deep nesting", () => {
  // Scanning and slicing the whole remainder for each level stripped is quadratic in n levels of
  // nesting, and at n = 32,000 (about 64 KB) it holds the main thread for seconds. Truncation by
  // token count happens after normalisation, so a long input arrives as is.
  const depth = 32_000;
  const started = performance.now();
  const normalized = normalizeText("「".repeat(depth) + "a" + "」".repeat(depth));
  const elapsed = performance.now() - started;
  assertEquals(normalized, "a");
  assert(elapsed < 1_000, `stripping ${depth} levels of nesting took ${elapsed.toFixed(0)} ms`);
});

test("outer-bracket stripping: matches the source of truth's sequential form on random inputs", () => {
  // The expected side is a direct copy of the source of truth `strip_outer_brackets` (scanning the
  // whole text for each level — quadratic, but fine for short inputs). The implementation computes
  // it linearly from a matching table, so random inputs check that the two forms do not diverge on
  // mixed brackets, brackets closing midway and unclosed brackets.
  const pairs: readonly (readonly [string, string])[] = [
    ["「", "」"],
    ["『", "』"],
    ["（", "）"],
    ["【", "】"],
    ["(", ")"],
  ];
  const reference = (text: string): string => {
    let cps = Array.from(text);
    while (cps.length >= 2) {
      const pair = pairs.find(([open]) => open === cps[0]);
      if (pair === undefined || cps[cps.length - 1] !== pair[1]) break;
      let depth = 0;
      let enclosing = true;
      for (const [index, ch] of cps.entries()) {
        if (ch === pair[0]) depth += 1;
        else if (ch === pair[1]) depth -= 1;
        if (depth === 0 && index < cps.length - 1) {
          enclosing = false;
          break;
        }
      }
      if (!enclosing || depth !== 0) break;
      cps = cps.slice(1, -1);
    }
    return cps.join("");
  };
  const alphabet = ["「", "」", "（", "）", "(", ")", "a"];
  let state = 12345;
  const nextIndex = (bound: number): number => {
    // A 32-bit LCG (`Math.imul` — a plain multiplication exceeds 2^53 and loses the low bits). The
    // low bits have a short period, so the upper 16 bits are used.
    state = (Math.imul(state, 1103515245) + 12345) >>> 0;
    return (state >>> 16) % bound;
  };
  let stripped = 0;
  for (let sample = 0; sample < 5_000; sample += 1) {
    const length = nextIndex(13);
    const raw = Array.from({ length }, () => alphabet[nextIndex(alphabet.length)]).join("");
    const expected = reference(raw);
    if (expected !== raw) stripped += 1;
    assertEquals(normalizeText(raw), expected.normalize("NFKC"), JSON.stringify(raw));
  }
  // The random inputs really exercise the stripping side (if everything passed through unchanged,
  // the comparison would be vacuous).
  assert(stripped >= 50, `only ${stripped} inputs get stripped`);
});

// ---- ⑥ The rare-token split (ADR 0149 — upstream's `RareTokenSplitter`) ------------------
//
// The fixture's split cases were solved by upstream with the split on (`enable_rare_token_split`)
// and off, on the real vocabulary. The synthetic vocabularies further down pin the boundaries the
// real cases cannot isolate.

test("split fixture: the cases are present and the split really changes most of them", () => {
  assertEquals(fixture.encode.split.length, 8);
  assertEquals(fixture.encode.split.filter((entry) => entry.idsPadded !== undefined).length, 4);
  const changed = fixture.encode.split.filter((entry) => !arraysEqual(entry.ids, entry.idsSplit));
  assert(changed.length >= 6, `only ${changed.length} split cases differ from the plain encoding`);
  // The split side's unknown-node weight comes from its own (replaced) minimum.
  assert(
    fixture.asset.rareTokenSplit.minScore < fixture.asset.minScore,
    "the split minScore is not below the original one",
  );
  assert(fixture.asset.rareTokenSplit.disabledIds.length > 0, "no disabled id is in the subset");
});

for (const testCase of fixture.encode.split) {
  test(`split parity [${testCase.name}] ${testCase.why}`, () => {
    assertEquals(normalizeText(testCase.raw).trim(), testCase.normalized, "the normalised string");
    assertEquals(splitTokenizer.encode(testCase.normalized, SPLIT), testCase.idsSplit, "split on");
    // The same tokenizer with the flag off is upstream's plain encoding (the table changes nothing
    // until it is asked for).
    assertEquals(splitTokenizer.encode(testCase.normalized, PLAIN), testCase.ids, "split off");
    assertEquals(tokenizer.encode(testCase.normalized, PLAIN), testCase.ids, "no table");
  });
}

for (const testCase of fixture.encode.split) {
  const { maxLength, idsPadded, mask, idsPaddedSplit, maskSplit } = testCase;
  if (maxLength === undefined) continue;
  test(`split assembly parity [${testCase.name}]`, () => {
    assert(idsPadded !== undefined && mask !== undefined, "the plain padded form is missing");
    assert(idsPaddedSplit !== undefined && maskSplit !== undefined, "the split form is missing");
    const plain = splitTokenizer.encodePadded(testCase.normalized, maxLength, PLAIN);
    assertEquals([...plain.ids], idsPadded, "idsPadded");
    assertEquals([...plain.mask], mask.map(Number), "mask");
    const split = splitTokenizer.encodePadded(testCase.normalized, maxLength, SPLIT);
    assertEquals([...split.ids], idsPaddedSplit, "idsPaddedSplit");
    assertEquals([...split.mask], maskSplit.map(Number), "maskSplit");
  });
}

test("split: truncation applies after the split (a body that fits unsplit is cut once split)", () => {
  const truncates = fixture.encode.split.find((entry) => entry.name === "split-truncates");
  assert(truncates?.maxLength !== undefined, "the fixture has no truncation-after-split case");
  const { maxLength } = truncates;
  assert(truncates.ids.length + 1 <= maxLength, "the plain body already overflows");
  assert(truncates.idsSplit.length + 1 > maxLength, "the split body does not overflow");
  const packed = packIds(splitTokenizer, truncates.raw, maxLength, "text", SPLIT);
  assertEquals([...packed], [fixture.asset.bosId, ...truncates.idsSplit.slice(0, maxLength - 1)]);
});

test("split: the caption path never splits, whatever tokenizer it gets", () => {
  // Upstream builds the caption tokenizer as a separate instance and never switches it.
  const commit = fixture.encode.split.find((entry) => entry.name === "split-commit-examples");
  assert(commit !== undefined, "the fixture has no commit-example case");
  assert(commit.raw === commit.normalized, "the case would also test normalisation");
  const caption = packCaptionIds(splitTokenizer, commit.raw, 512);
  assertEquals([...caption], [fixture.asset.bosId, ...commit.ids]);
  // The text path of the same tokenizer and string does split (the caption side is not equal by
  // accident).
  assertEquals(
    [...packIds(splitTokenizer, commit.raw, 512, "text", SPLIT)],
    [fixture.asset.bosId, ...commit.idsSplit],
  );
});

/** Element-wise equality of two id lists. */
const arraysEqual = (left: readonly number[], right: readonly number[]): boolean =>
  left.length === right.length && left.every((value, index) => value === right[index]);

/**
 * A synthetic vocabulary for the split boundaries. `abcd` is disabled (its pieces `ab` / `cd`
 * exist), `xy` is forced to `x` + `y`, and `pq` is disabled although `p` / `q` are not in the
 * vocabulary at all (only an unknown piece could replace it).
 */
const SPLIT_VOCAB: readonly (readonly [string, number])[] = [
  ["<unk>", 0],
  ["<s>", 0],
  ["<pad>", 0],
  ["abcd", -14],
  ["ab", -8],
  ["cd", -8],
  ["xy", -3],
  ["x", -4],
  ["y", -4],
  ["pq", -14],
];

const syntheticAssets = (): IrodoriTokenizerAssets => ({
  vocab: new Map(SPLIT_VOCAB.map(([token, score], id) => [token, { id, score }])),
  minScore: -14,
  maxTokenLength: 4,
  unkId: 0,
  byteBaseId: 100,
  bosId: 1,
  padId: 2,
  addedTokens: new Map(),
});

const syntheticSplit = (minScore: number = -1e9): IrodoriTokenizer =>
  new IrodoriTokenizer({
    ...syntheticAssets(),
    rareTokenSplit: {
      disabledScore: -1e9,
      disabledIds: [3, 9],
      minScore,
      forcedSplits: new Map([[6, [7, 8]]]),
    },
  });

test("split: a disabled token falls back to shorter pieces", () => {
  assertEquals(syntheticSplit().encode("abcd", PLAIN), [3]);
  assertEquals(syntheticSplit().encode("abcd", SPLIT), [4, 5]);
});

test("split: a forced id expands to its pieces after the lattice is solved", () => {
  // `xy` (-3) beats `x` + `y` (-8) in the lattice, so only the forced table splits it.
  assertEquals(syntheticSplit().encode("xy", PLAIN), [6]);
  assertEquals(syntheticSplit().encode("xy", SPLIT), [7, 8]);
});

test("split: encodePadded cuts the body after the split", () => {
  const tokenizer = syntheticSplit();
  // Split body [4, 5, 7, 8] cut to maxLength − 1 = 3; the plain body [3, 6] fits.
  assertEquals([...tokenizer.encodePadded("abcdxy", 4, SPLIT).ids], [1, 4, 5, 7]);
  assertEquals([...tokenizer.encodePadded("abcdxy", 4, PLAIN).ids], [1, 3, 6, 2]);
});

test("split: the caption pack ignores the table while the text pack uses it", () => {
  assertEquals([...packCaptionIds(syntheticSplit(), "abcdxy", 8)], [1, 3, 6]);
  assertEquals([...packIds(syntheticSplit(), "abcdxy", 8, "text", SPLIT)], [1, 4, 5, 7, 8]);
});

test("split: an unknown piece costs the replaced minimum − 10, so a disabled token without pieces stays", () => {
  // Under the split model the unknown node of `p` / `q` costs -1e9 − 10 each, below the disabled
  // `pq` (-1e9): upstream's copy keeps emitting `pq`. Removing the entry instead, or keeping the
  // original minimum (-14 → unknown = -24), would turn it into bytes.
  assertEquals(syntheticSplit().encode("pq", SPLIT), [9]);
  const staleMinimum = syntheticSplit(-14);
  assertEquals(
    staleMinimum.encode("pq", SPLIT),
    [...new TextEncoder().encode("pq")].map((byte) => 100 + byte),
    "evidence the check above depends on the minimum",
  );
});

test("split: asking for the split without a table fails loudly", () => {
  const plain = new IrodoriTokenizer(syntheticAssets());
  assertEquals(plain.hasRareTokenSplit, false);
  assertEquals(syntheticSplit().hasRareTokenSplit, true);
  assertThrows(() => plain.encode("abcd", SPLIT), Error, "carries no rareTokenSplit table");
  assertThrows(() => plain.encodePadded("abcd", 4, SPLIT), Error, "carries no rareTokenSplit");
  // The plain path of the same tokenizer still works.
  assertEquals(plain.encode("abcd", PLAIN), [3]);
});

// ---- ⑥' The asset parser of the split table ------------------------------------

/** A parseable asset over {@link SPLIT_VOCAB} + 256 byte rows, with an optional split table. */
const splitAssetJson = (rareTokenSplit?: unknown): Record<string, unknown> => {
  const { vocabText, scores, byteBaseId } = padVocabForByteBase(
    SPLIT_VOCAB.map(([token]) => token),
    SPLIT_VOCAB.map(([, score]) => score),
  );
  return {
    vocabText,
    scores,
    addedTokens: [],
    bosId: 1,
    padId: 2,
    unkId: 0,
    byteBaseId,
    ...(rareTokenSplit === undefined ? {} : { rareTokenSplit }),
  };
};

const VALID_SPLIT = { disabledScore: -1e9, disabledIds: [3, 9], forcedSplits: [[6, [7, 8]]] };

test("asset parser: reads the split table and computes the replaced-score minimum from the whole vocabulary", () => {
  const parsed = parseIrodoriTokenizerAsset(splitAssetJson(VALID_SPLIT));
  assert(parsed.rareTokenSplit !== undefined, "the table was dropped");
  assertEquals(parsed.rareTokenSplit.disabledIds, [3, 9]);
  assertEquals(parsed.rareTokenSplit.disabledScore, -1e9);
  assertEquals([...parsed.rareTokenSplit.forcedSplits], [[6, [7, 8]]]);
  assertEquals(parsed.minScore, -14, "the original minimum is unchanged");
  assertEquals(parsed.rareTokenSplit.minScore, -1e9, "the split minimum is the replaced one");
  assertEquals(new IrodoriTokenizer(parsed).encode("abcdxy", SPLIT), [4, 5, 7, 8]);
  // An asset without the key (an older revision) has no split path.
  assertEquals(parseIrodoriTokenizerAsset(splitAssetJson()).rareTokenSplit, undefined);
});

test("asset parser: a malformed split table is an asset error", () => {
  const VOCAB_SIZE = SPLIT_VOCAB.length + 256;
  const broken: readonly (readonly [unknown, string])[] = [
    ["table", "tokenizer.rareTokenSplit: not an object"],
    [{ ...VALID_SPLIT, disabledScore: Number.NaN }, "disabledScore: not a finite number"],
    [{ ...VALID_SPLIT, disabledScore: "-1e9" }, "disabledScore: not a finite number"],
    [{ ...VALID_SPLIT, disabledIds: "3,9" }, "disabledIds: not an array"],
    [
      { ...VALID_SPLIT, disabledIds: [3, VOCAB_SIZE] },
      `disabledIds[1]: token id ${VOCAB_SIZE} is not below the vocabulary row count`,
    ],
    [{ ...VALID_SPLIT, disabledIds: [3, 2.5] }, "disabledIds[1]: token id is not an integer"],
    [
      { ...VALID_SPLIT, disabledIds: [9, 3] },
      "disabledIds[1]: id 3 is not above the previous id 9",
    ],
    [
      { ...VALID_SPLIT, disabledIds: [3, 3] },
      "disabledIds[1]: id 3 is not above the previous id 3",
    ],
    [{ ...VALID_SPLIT, forcedSplits: [[6]] }, "forcedSplits[0]: not a [tokenId, pieces] pair"],
    [
      {
        ...VALID_SPLIT,
        forcedSplits: [
          [6, [7]],
          [6, [8]],
        ],
      },
      "id 6 is not above the previous id 6",
    ],
    [{ ...VALID_SPLIT, forcedSplits: [[6, []]] }, "forcedSplits[0][1]: token 6 has no pieces"],
    [
      { ...VALID_SPLIT, forcedSplits: [[6, [7, VOCAB_SIZE]]] },
      `forcedSplits[0][1][1]: token id ${VOCAB_SIZE} is not below`,
    ],
    [
      { ...VALID_SPLIT, forcedSplits: [[VOCAB_SIZE, [7]]] },
      "is not below the vocabulary row count",
    ],
  ];
  for (const [table, message] of broken) {
    assertThrows(
      () => parseIrodoriTokenizerAsset(splitAssetJson(table)),
      Error,
      message,
      JSON.stringify(table),
    );
  }
});
